// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 callerSeed, uint256 warpTime) public {
        warpTime = bound(warpTime, 1, type(uint32).max);

        AcceptingCaller caller = new AcceptingCaller();

        vm.deal(address(caller), 0);

        uint256 sendAmt = 10 ether;
        vm.deal(address(this), sendAmt);

        vm.warp(warpTime);

        uint64 targetBlock = 15;
        uint256 multiple = 1 + (callerSeed % 1000);
        targetBlock = uint64(15 * multiple);
        vm.roll(targetBlock);

        vm.deal(address(caller), sendAmt);
        caller.callFallback{value: sendAmt}(address(c));

        assertTrue(address(c).balance == 0);
    }
}

contract AcceptingCaller {
    receive() external payable {}

    function callFallback(address target) external payable {
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok, "call failed");
    }
}
